<?php
/**
 * Production deploy: curated Aceites + Carnes commercial SEO landings.
 * Spanish native pages + reviewed English aliases/content in _en_US_* metadata.
 * Idempotent by _emdo_ac_landing_key.
 */
if (!defined('ABSPATH')) { fwrite(STDERR, "WordPress is not loaded.\n"); exit(1); }

function emdo_ac_products_shortcode(array $ids): string {
    $ids = array_values(array_unique(array_filter(array_map('intval', $ids), static fn($id) => get_post_status($id) === 'publish')));
    if (!$ids) return '';
    return '[products ids="'.implode(',', $ids).'" columns="3" orderby="post__in"]';
}

function emdo_ac_aioseo(int $post_id, string $title, string $description): void {
    global $wpdb;
    $table = $wpdb->prefix . 'aioseo_posts';
    if ($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s', $table)) !== $table) return;
    $row_id = (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM `{$table}` WHERE post_id=%d LIMIT 1", $post_id));
    if ($row_id) $wpdb->update($table, array('title'=>$title,'description'=>$description), array('id'=>$row_id), array('%s','%s'), array('%d'));
}

function emdo_ac_page_id(string $key): int {
    $ids = get_posts(array('post_type'=>'page','post_status'=>array('publish','draft','private'),'posts_per_page'=>2,'fields'=>'ids','no_found_rows'=>true,'meta_key'=>'_emdo_ac_landing_key','meta_value'=>$key));
    return $ids ? (int)$ids[0] : 0;
}

function emdo_ac_render(array $cfg, string $lang, string $products): string {
    $d = $cfg[$lang];
    $html = '';
    foreach ($d['intro'] as $p) $html .= '<p>'.$p.'</p>\n';
    $html .= $products."\n";
    foreach ($d['sections'] as $heading => $paragraphs) {
        $html .= '<h2>'.$heading.'</h2>\n';
        foreach ($paragraphs as $p) $html .= '<p>'.$p.'</p>\n';
    }
    if (!empty($d['bullets'])) {
        foreach ($d['bullets'] as $heading => $items) {
            $html .= '<h2>'.$heading.'</h2><ul>';
            foreach ($items as $item) $html .= '<li>'.$item.'</li>';
            $html .= '</ul>\n';
        }
    }
    $html .= '<h2>'.$d['faq_title'].'</h2>\n';
    foreach ($d['faq'] as $q => $a) $html .= '<h3>'.$q.'</h3><p>'.$a.'</p>\n';
    $html .= $products."\n";
    return $html;
}

function emdo_ac_upsert(array $cfg): array {
    $products = emdo_ac_products_shortcode($cfg['products']);
    if ($products === '') throw new Exception('No live products for '.$cfg['key']);
    $id = emdo_ac_page_id($cfg['key']);
    if (!$id) {
        $existing = get_page_by_path($cfg['es_slug'], OBJECT, 'page');
        if ($existing instanceof WP_Post) $id = (int)$existing->ID;
    }
    $es_content = emdo_ac_render($cfg, 'es', $products);
    $en_content = emdo_ac_render($cfg, 'en', $products);
    $args = array('post_type'=>'page','post_status'=>'publish','post_title'=>$cfg['es_title'],'post_name'=>$cfg['es_slug'],'post_content'=>$es_content,'post_excerpt'=>$cfg['es_meta'],'comment_status'=>'closed','ping_status'=>'closed');
    if ($id) $args['ID'] = $id;
    $saved = wp_insert_post(wp_slash($args), true);
    if (is_wp_error($saved)) throw new Exception($saved->get_error_message());
    $id = (int)$saved;
    update_post_meta($id, '_emdo_ac_landing_key', $cfg['key']);
    update_post_meta($id, '_en_US_post_title', '<span data-no-translation>'.$cfg['en_title'].'</span>');
    update_post_meta($id, '_en_US_post_name', $cfg['en_slug']);
    update_post_meta($id, '_en_US_post_excerpt', $cfg['en_meta']);
    update_post_meta($id, '_en_US_post_content', '<span data-no-translation>'.$en_content.'</span>');
    update_post_meta($id, '_en_US_published', '1');
    emdo_ac_aioseo($id, $cfg['seo_title'], $cfg['es_meta']);
    return array('key'=>$cfg['key'],'group'=>$cfg['group'],'id'=>$id,'es_url'=>home_url('/'.$cfg['es_slug'].'/'),'en_url'=>home_url('/en/'.$cfg['en_slug'].'/'),'products'=>array_values(array_filter(array_map('intval',$cfg['products']), static fn($pid)=>get_post_status($pid)==='publish')));
}

function emdo_ac_link_category(string $slug, array $pages): void {
    $term = get_term_by('slug', $slug, 'product_cat');
    if (!$term || is_wp_error($term)) throw new Exception('Missing product category '.$slug);
    $start='<!-- emdo-ac-landings-start -->'; $end='<!-- emdo-ac-landings-end -->';
    $pattern='/\\s*'.preg_quote($start,'/').'.*?'.preg_quote($end,'/').'\\s*/s';
    $es=(string)$term->description; $es=preg_replace($pattern,"\n",$es);
    $en=(string)get_term_meta((int)$term->term_id,'_en_US_description',true); if($en!=='') $en=preg_replace($pattern,"\n",$en);
    $es_links=array(); $en_links=array();
    foreach($pages as $p){
        $es_links[]='<a href="'.esc_url($p['es_url']).'">'.esc_html($p['es_title']).'</a>';
        $en_links[]='<a href="'.esc_url($p['en_url']).'">'.esc_html($p['en_title']).'</a>';
    }
    $es_block=$start.'<div class="emdo-seo-landings"><p><strong>Explora también:</strong> '.implode(' · ',$es_links).'</p></div>'.$end;
    $r=wp_update_term((int)$term->term_id,'product_cat',array('description'=>trim($es)."\n\n".$es_block));
    if(is_wp_error($r)) throw new Exception($r->get_error_message());
    if($en!==''){
        $en_block=$start.'<div class="emdo-seo-landings"><p><strong>Explore also:</strong> '.implode(' · ',$en_links).'</p></div>'.$end;
        update_term_meta((int)$term->term_id,'_en_US_description',trim($en)."\n\n".$en_block);
    }
}

